/**
 * Static server for the eval-4 viewer.
 *
 *   node mcp-eval-4/serve.mjs [port]
 *
 * Exists instead of `python3 -m http.server` for one reason: this
 * viewer is regenerated by build-viewer.mjs on every run, and the
 * stock server sends no Cache-Control, so browsers apply heuristic
 * caching and a tab opened before a rebuild keeps showing the old
 * page with no sign anything changed. Everything here is no-store.
 */

import { createServer } from "node:http";
import { readFile, stat } from "node:fs/promises";
import { extname, join, normalize, resolve } from "node:path";

const ROOT = resolve(import.meta.dirname);
const PORT = Number(process.argv[2] ?? 4041);

const TYPES = {
  ".html": "text/html; charset=utf-8",
  ".css": "text/css; charset=utf-8",
  ".js": "text/javascript; charset=utf-8",
  ".mjs": "text/javascript; charset=utf-8",
  ".json": "application/json; charset=utf-8",
  ".md": "text/plain; charset=utf-8",
  ".png": "image/png",
  ".webp": "image/webp",
  ".jpg": "image/jpeg",
  ".svg": "image/svg+xml",
};

createServer(async (req, res) => {
  try {
    const url = new URL(req.url, "http://localhost");
    // normalize() collapses any ../ before the prefix check, so a
    // crafted path cannot escape the eval directory.
    let path = resolve(ROOT, "." + normalize(decodeURIComponent(url.pathname)));
    if (!path.startsWith(ROOT)) return end(res, 403, "forbidden");

    const info = await stat(path).catch(() => null);
    if (info?.isDirectory()) path = join(path, "index.html");

    const body = await readFile(path).catch(() => null);
    if (!body) return end(res, 404, "not found");

    res.writeHead(200, {
      "content-type": TYPES[extname(path)] ?? "application/octet-stream",
      // The whole point: the viewer is rebuilt constantly.
      "cache-control": "no-store, must-revalidate",
    });
    res.end(body);
  } catch {
    end(res, 500, "error");
  }
}).listen(PORT, () => {
  console.log(`eval-4 viewer  →  http://localhost:${PORT}/  (no-store)`);
});

function end(res, code, msg) {
  res.writeHead(code, { "content-type": "text/plain; charset=utf-8" });
  res.end(msg + "\n");
}
